class NomFormaCalculo extends BaseNomFormaCalculo {

    /**
     * Obtener todas las formas de cálculo.
     * 
     * @return array    Listado de los datos de las formas de cálculo.
     */
    public static function obtenerTodasFormasCalculo() {

        //Devolviendo el listado de de las formas de cálculo en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomFormaCalculo')
                ->fetchArray();
    }
	
	/**
     * Obtener las formas de cálculo dado un array de identificadores.
     * 
     * @param array $id         Identificadores de la forma de cálculo.
     *
     * @return array    Listado de los datos de las formas de cálculo.
     */
    public static function obtenerFormasCalculoDadoArrayIds($id) {

        //Devolviendo el listado de las formas de cálculo en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomFormaCalculo')
                ->whereIn('idformacalculo', $id)
                ->fetchArray();
    }
}